"""Per-scope runtime config accessor.

Each scope gets its own isolated store keyed on the scope_id, so one caller's writes are invisible
to every other caller (fixes INC-9923, where a single shared module-global `_CONFIG` let request A
read back request B's `last_user`).
"""

_STORES = {}          # scope_id -> {key: value} -- one isolated dict per scope


def open_scope(scope_id):
    _STORES.setdefault(scope_id, {})


def set_value(scope_id, key, value):
    _STORES.setdefault(scope_id, {})[key] = value


def get_value(scope_id, key):
    return _STORES.get(scope_id, {}).get(key)


def close_scope(scope_id):
    _STORES.pop(scope_id, None)

